import{_ as l,o as a,c as e,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Month 2021: RADOS Update","description":"","frontmatter":{"title":"Ceph Month 2021: RADOS Update","date":"2021-06-01T00:00:00.000Z","updated":"2021-06-02T00:00:00.000Z","tags":["Ceph","Distributed Storage","RADOS","Quincy","Pacific"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Month_2021_-_RADOS_Update.md","filePath":"posts/2021/Ceph_Month_2021_-_RADOS_Update.md","lastUpdated":1780459816000}'),o={name:"posts/2021/Ceph_Month_2021_-_RADOS_Update.md"};function r(n,i,s,h,c,u){return a(),e("div",null,[...i[0]||(i[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph-pacific-更新及-quincy-展望" tabindex="-1">会议主题：Ceph Pacific 更新及 Quincy 展望 <a class="header-anchor" href="#会议主题-ceph-pacific-更新及-quincy-展望" aria-label="Permalink to &quot;会议主题：Ceph Pacific 更新及 Quincy 展望&quot;">​</a></h4><h4 id="会议时间-具体时间" tabindex="-1">会议时间：[具体时间] <a class="header-anchor" href="#会议时间-具体时间" aria-label="Permalink to &quot;会议时间：[具体时间]&quot;">​</a></h4><h4 id="会议地点-具体地点" tabindex="-1">会议地点：[具体地点] <a class="header-anchor" href="#会议地点-具体地点" aria-label="Permalink to &quot;会议地点：[具体地点]&quot;">​</a></h4><h4 id="参会人员" tabindex="-1">参会人员： <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员：&quot;">​</a></h4><ul><li>Neha Ocha（技术负责人，Raiders 团队）</li></ul><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><strong>Ceph Pacific 更新</strong><ul><li><strong>可用性增强</strong>： <ul><li>Upmap 平衡器默认开启，提升数据平衡效率。</li><li>新增健康警告，检测不同版本的守护进程并提醒用户。</li><li>支持取消正在进行的数据一致性检查（scrubs）。</li><li>改进恢复进度显示，提供更全面的恢复进度信息。</li><li>引入分布式追踪框架，使用 Jaeger 工具在 OSD 中添加追踪点。</li></ul></li><li><strong>质量提升</strong>： <ul><li>改进 PG 删除性能，提升 4 倍。</li><li>优化 OSD 映射修剪行为，仅保留相关版本。</li><li>更新 Messenger 2.1，引入新的安全修复。</li><li>改进管理器模块效率，包括进度模块的可关闭性。</li><li>优化大型 C++ 结构的使用，减少冗余信息。</li></ul></li><li><strong>性能优化</strong>： <ul><li>RocksDB 分片默认开启，减少磁盘空间需求。</li><li>引入混合分配器，降低内存使用和磁盘碎片。</li><li>SSD 的 4K 分配单元大小，提高空间利用率。</li><li>改进缓存效率，引入 mempools 概念，便于内存使用追踪。</li></ul></li><li><strong>生态系统</strong>： <ul><li>支持扩展集群配置，跨数据中心配置带有仲裁器的集群。</li></ul></li></ul></li><li><strong>Quincy 展望</strong><ul><li><strong>可用性增强</strong>： <ul><li>mClock 调度器将成为默认设置，简化配置。</li><li>引入自动基准测试，优化 mClock 参数。</li><li>新的 PG 自动扩展器配置文件，支持缩减操作。</li><li>改进平衡器算法，考虑 OSD 利用率。</li><li>提供更详细的集群降级信息。</li></ul></li><li><strong>质量提升</strong>： <ul><li>动态调整监控器修剪速率，防止积压。</li><li>进一步改进 PG 删除性能。</li><li>管理器模块的自动调整统计收集频率。</li><li>改进慢操作日志记录，简化日志监控代码。</li></ul></li><li><strong>性能优化</strong>： <ul><li>扩展 QoS 支持，包括 HDD 和背景活动优先级。</li><li>移除 RocksDB 中的分配元数据，提高写入性能。</li><li>简化拆分缓存，避免锁定问题。</li><li>引入 omap 性能基准测试工具。</li></ul></li><li><strong>生态系统</strong>： <ul><li>自动生成文档，减少重复工作。</li><li>集成 Redmine 追踪器，优化资产标识。</li></ul></li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>继续优化和扩展 QoS 功能，包括客户端和池级别的优先级设置。</li><li>完善 Crimson 和 C-Store 的支持，包括多核支持和持久内存支持。</li><li>加强生态系统建设，提高文档自动化和用户反馈收集。</li></ul><h4 id="会议结束语" tabindex="-1">会议结束语： <a class="header-anchor" href="#会议结束语" aria-label="Permalink to &quot;会议结束语：&quot;">​</a></h4><p>会议在讨论了 Ceph Pacific 的最新进展和 Quincy 的未来规划后结束，Neha Ocha 邀请大家提出问题并进行了简短的问答环节。会议随后转向了 Windows 相关的内容。</p>',12)])])}const _=l(o,[["render",r]]);export{p as __pageData,_ as default};
